function button(action,label,fid='',extra=''){return `<button type="button" data-rp="${action}" data-id="${esc(fid)}" ${extra}>${label}</button>`}
function activeEquipment(f){let loadout=(f.loadouts||[]).find(x=>x.active);return {loadout,items:loadout?(f.equipment||[]).filter(e=>(loadout.equipmentIds||[]).includes(e.id)):(f.equipment||[])}}
function catalogItem(item){return [...(R().equipment||[]),...(data.customAssets?.equipment||[])].find(x=>x.id===(item.catalogId||item.presetId||item.customAssetId))}
function profiles(item){let actual=item.profiles||item.weaponProfiles||item.weapon_profiles;if(!actual?.length){let base=catalogItem(item);actual=base?.weaponProfiles||base?.weapon_profiles||[]}return window.FighterParity?.equipmentProfiles?FighterParity.equipmentProfiles({...item,profiles:actual||[]}):actual||[]}
