function weaponRows(items){let grouped=new Map();for(let item of items){for(let profile of profiles(item)){let key=JSON.stringify([item.customAssetId||item.catalogId||item.presetId||item.name,item.name,profile,item.masterCrafted,item.effects||[]]),row=grouped.get(key);if(row)row.quantity+=Math.max(1,number(item.quantity)||1);else grouped.set(key,{profile,item,quantity:Math.max(1,number(item.quantity)||1)})}}return [...grouped.values()].sort((a,b)=>String(a.profile.profile_name||a.profile.name||a.item.name).localeCompare(String(b.profile.profile_name||b.profile.name||b.item.name)))}
function weaponTable(g,f,items){let rows=weaponRows(items);if(!rows.length)return '';let is26=g.edition==='N26',crew=names(f.subtypes).includes('Crew'),label=crew?'Crew Weapon':'Weapon';return `<div class="rp-weapon-wrap"><table class="rp-weapons"><thead>${is26?`<tr><th>${label}</th><th>SR</th><th>LR</th><th>Str</th><th>AP</th><th>L</th><th>Traits</th></tr>`:`<tr class="rp-weapon-groups"><th rowspan="2">${label}</th><th colspan="2">Rng</th><th colspan="2">Acc</th><th colspan="5"></th></tr><tr><th>S</th><th>L</th><th>S</th><th>L</th><th>Str</th><th>AP</th><th>D</th><th>Am</th><th>Traits</th></tr>`}</thead><tbody>${rows.map(({profile:p,item,quantity})=>{let title=p.profile_name||p.name||item.name,traits=Array.isArray(p.traits)?[...p.traits]:p.traits?[String(p.traits)]:[],traitText=traits.join(', ');if(item.masterCrafted&&!/\bMaster-crafted\b/i.test(traitText))traits.push('Master-crafted');if(crew&&!/(?:^|,)\s*Arc\b/i.test(traitText))traits.push('Arc (Front)');if(item.hardpointArcs?.length)traits.push('Arc ('+item.hardpointArcs.join(', ')+')');return `<tr><td>${button('equipment',(window.MMEquipmentUsage?.profileTitle(p,item,g.edition,{scope:false})||esc(title))+(quantity>1&&!title.startsWith('-')?` (x${quantity})`:''),f.id,`data-equipment="${item.id}" class="rp-weapon-link"`)}${item.effects?.length?`<small class="rp-effect-note">${item.effects.map(e=>esc(e.name)).join(', ')}</small>`:''}</td><td>${esc(range(p.range_short??p.short_range??p.rangeShort))}</td><td>${esc(range(p.range_long??p.long_range??p.rangeLong))}</td>${is26?'':`<td>${esc(accuracy(p.acc_short??p.accuracy_short))}</td><td>${esc(accuracy(p.acc_long??p.accuracy_long))}</td>`}<td>${esc(p.strength??p.S??'—')}</td><td>${esc(emptyZero(p.ap??p.AP))}</td>${is26?`<td>${esc(emptyZero(p.lethality??p.L))}</td>`:`<td>${esc(emptyZero(p.damage??p.D))}</td><td>${esc(emptyZero(p.ammo))}</td>`}<td>${traitMarkup(traits,g.edition)}</td></tr>`}).join('')}</tbody></table></div>`}
function aggregate(items){let counts=new Map;for(let item of items){let name=typeof item==='string'?item:item.name||item.effect_name||item.equipment_name||'',qty=typeof item==='string'?1:Math.max(1,number(item.quantity)||1);if(name)counts.set(name,(counts.get(name)||0)+qty)}return [...counts].sort(([a],[b])=>a.localeCompare(b)).map(([name,count])=>esc(name)+(count>1?` (x${count})`:'')).join(', ')}
function details(f,items){let wargear=items.filter(e=>!profiles(e).length),skills=names(f.skills),rules=new Set(names(f.specialRules||f.special_rules));for(let e of items)for(let rule of names(e.grantedSpecialRules))rules.add(rule);let injuries=(f.injuries||[]).filter(i=>!i.isGlitch),glitches=(f.injuries||[]).filter(i=>i.isGlitch||i.category==='rig-glitches'),rows=[];if(wargear.length)rows.push(['Wargear',aggregate(wargear)]);if(skills.length||f.freeSkill||f.free_skill)rows.push(['Skills',skills.sort((a,b)=>a.localeCompare(b)).map(esc).join(', ')+((f.freeSkill??f.free_skill)?'<div class="rp-missing-skill">⚠ Starting skill missing.</div>':'')]);if(rules.size)rows.push(['Special Rules',[...rules].map(esc).join(', ')]);if(injuries.length)rows.push(['Last. Injuries',aggregate(injuries.map(i=>({...i,name:i.name+(i.hatredTargetName?' ('+i.hatredTargetName+')':'')})))]);if(glitches.length)rows.push(['Rig Glitches',aggregate(glitches)]);if(f.damages?.length)rows.push(['Damage',aggregate(f.damages)]);if(f.notes)rows.push(['Notes',safeNote(f.notes)]);return rows.length?`<dl class="rp-details">${rows.map(([label,body])=>`<dt>${label}</dt><dd>${body}</dd>`).join('')}</dl>`:''}
function statusIcon(f){return ({Dead:'☠',Retired:'♧',Enslaved:'⛓','In Recovery':'✚',Captured:'⛓',Starved:'♨',Destroyed:'☠'})[f.status]||''}
function rosterCard(g,f){let {loadout,items}=activeEquipment(f),inactive=['Dead','Retired','Enslaved','In Recovery','Destroyed'].includes(f.status),portrait=window.FighterParity?.portraitSource(f),label=names(f.subtypes||f.fighter_subtypes),owner=g.fighters.find(x=>x.id===(f.ownerId||f.owner_id)),type=[f.type+(label.length?' ('+label.join(', ')+')':''),f.variant||f.fighter_variant,f.specialisation].filter(Boolean).join(', ');return `<article class="rp-card-shell" data-rp-fighter="${f.id}" draggable="true"><a href="/fighter/${f.id}" class="rp-card ${inactive?'rp-inactive':''}" data-rp="open" data-id="${f.id}" role="link" tabindex="0" aria-label="Open ${esc(f.name)}"><div class="rp-card-inner"><header class="rp-card-header"><div class="rp-title">${f.label?`<span class="rp-label">${esc(f.label)}</span>`:''}<div><h3>${esc(f.name)}</h3><p>${esc(type)}</p></div></div><div class="rp-card-tokens">${statusIcon(f)?`<span class="rp-status-icon rp-status-${f.status.toLowerCase().replace(/\s/g,'-')}" title="${esc(f.status)}" aria-label="${esc(f.status)}">${statusIcon(f)}</span>`:''}${portrait?`<img class="rp-portrait" src="${esc(portrait)}" alt="${esc(f.name)}">`:''}${!inactive?`<div class="rp-credit-disc"><strong>${totalCost(f,items)===0?'*':fmt(totalCost(f,items))}</strong><span>Credits</span></div>`:''}</div></header>${inactive?'':`<div class="rp-body">${loadout||owner||f.status==='Captured'?`<p class="rp-card-context">${loadout?'Loadout: <strong>'+esc(loadout.name)+'</strong>':''}${loadout&&owner?' — ':''}${owner?'Owned by <strong>'+esc(owner.name)+'</strong>':''}${f.status==='Captured'?' · Captured by: <strong>'+esc(data.gangs.find(x=>x.id===f.capturedBy)?.name||f.capturedByGangName||'Unknown gang')+'</strong>':''}</p>`:''}${statTable(g,f,items)}${weaponTable(g,f,items)}${details(f,items)}</div>`}</div></a>${button('menu','⋮',f.id,'class="rp-card-menu" aria-label="Fighter actions" title="Click to open action menu"')}</article>`}
function orderedFighters(g){let order=g.fighterOrder||Object.entries(g.positioning||{}).sort(([a],[b])=>number(a)-number(b)).map(([,v])=>v),lookup=new Map(g.fighters.map(f=>[f.id,f])),out=order.map(fid=>lookup.get(fid)).filter(Boolean);for(let f of g.fighters)if(!out.includes(f))out.push(f);return out.filter(f=>!f.beastEquipmentStashed&&!f.beast_equipment_stashed)}
gangMainTab=function(g){let mode=['normal','2-card','3-card','4-card'].includes(data.rosterView)?data.rosterView:'normal';return `<div class="rp-roster rp-view-${mode}" data-roster-view="${mode}">${orderedFighters(g).map(f=>rosterCard(g,f)).join('')||'<p class="rp-roster-empty"><i>No fighters added yet.</i></p>'}</div><section class="rp-print-details"><h2>Additional Details</h2>${g.notes?`<div>${safeNote(g.notes)}</div>`:''}${g.stash?.length?`<p>Stash: ${aggregate(g.stash)}</p>`:''}</section>`};
const oldGangTop=gangTop;gangTop=function(g){let mode=['normal','2-card','3-card','4-card'].includes(data.rosterView)?data.rosterView:'normal',view=`<select class="rp-view-select" data-rp-view aria-label="Page view"><option value="normal" ${mode==='normal'?'selected':''}>Page View</option>${[2,3,4].map(n=>`<option value="${n}-card" ${mode===n+'-card'?'selected':''}>${n}-card View</option>`).join('')}</select>`,html=oldGangTop(g);return html.replace(/<button[^>]*data-parity="view-mode"[^>]*>[\s\S]*?<\/button>/,view)};
function closeMenu(restoreFocus=false){let anchor=menuAnchor;menu?.remove();menu=null;menuAnchor=null;if(restoreFocus&&anchor?.isConnected)anchor.focus({preventScroll:true})}
function openMenu(anchor,f){closeMenu();menuAnchor=anchor;let rect=anchor.getBoundingClientRect();menu=document.createElement('div');menu.className='rp-action-menu';menu.role='menu';menu.innerHTML=button('xp','Add XP',f.id,'role="menuitem"')+button('injury',/spyrer/i.test(gang().faction)||f.isSpyrer?'Add Rig Glitches':'Add Lasting Injuries',f.id,'role="menuitem"')+((f.isVehicle||names(f.subtypes).includes('Crew'))?button('damage','Add Lasting Damage',f.id,'role="menuitem"'):'')+(f.status==='Captured'?button('restore','Rescue Fighter',f.id,'role="menuitem"'):'')+(f.status==='Dead'?button('restore','Resurrect Fighter',f.id,'role="menuitem"'):'');document.body.append(menu);menu.style.top=Math.min(window.innerHeight-menu.offsetHeight-8,rect.bottom+7)+'px';menu.style.left=Math.max(8,Math.min(window.innerWidth-210,rect.right-200))+'px';menu.querySelector('button')?.focus()}
function equipmentInfo(f,e){let g=gang(),body=weaponTable(g,f,[e]);showModal(esc(e.name),body||`<p>${esc(e.description||e.category||e.equipmentType||'Equipment')}</p>`,'Close',()=>true);$('.modal').classList.add('rp-equipment-dialog');$('#modal-cancel').hidden=true}
function lastingDamage(f){let rules=(R().effects||[]).filter(x=>x.category==='lasting damages'&&(!x.edition_slug||x.edition_slug===gang().edition.toLowerCase())),choices=rules.map(x=>({value:x.id,label:x.name||x.effect_name}));formModal('Add Lasting Damage',MMWidgets.combo('damage','Lasting Damage',[{value:'',label:'Select Lasting Damage'},...choices],'','Select Lasting Damage'),v=>{let rule=rules.find(x=>x.id===v.damage);if(!rule)return false;f.damages??=[];let record={id:id(),name:rule.name||rule.effect_name,catalogId:rule.id,at:now()};f.damages.push(record);f.effects??=[];let alias={movement:'M',weapon_skill:'WS',ballistic_skill:'BS',strength:'S',toughness:'T',wounds:'W',initiative:'I',attacks:'A',save:'Sv',leadership:'Ld',cool:'Cl',willpower:'Wil',intelligence:'Int'};for(let modifier of rule.modifiers||[]){let stat=alias[modifier.stat_name]||modifier.stat_name;f.effects.push({id:id(),damageId:record.id,name:record.name,category:'Lasting Damage',stat,amount:number(modifier.default_numeric_value??modifier.numeric_value),operation:modifier.operation})}if(rule.type_specific_data?.recovery==='true')f.status='In Recovery';log(gang(),`${f.name}: ${record.name}`);save()},'Add Damage')}
function reorder(from,to){let g=gang();if(!g||!from||!to||from===to)return;let rows=orderedFighters(g),a=rows.findIndex(x=>x.id===from),b=rows.findIndex(x=>x.id===to);if(a<0||b<0)return;let [moved]=rows.splice(a,1);rows.splice(b,0,moved);g.fighterOrder=rows.map(x=>x.id);g.positioning=Object.fromEntries(rows.map((f,i)=>[i,f.id]));g.fighters=[...rows,...g.fighters.filter(f=>!rows.includes(f))];log(g,`${moved.name}: roster position updated`);save()}
function resizeCards(){resizeObserver?.disconnect();let roster=$('.rp-roster');if(!roster||roster.dataset.rosterView==='normal')return;let resize=shell=>{let inner=shell.querySelector('.rp-card-inner'),card=shell.querySelector('.rp-card'),scale=Math.max(.08,(shell.clientWidth-4)/720);inner.style.width='720px';inner.style.transform=`scale(${scale})`;card.style.height=Math.ceil(inner.scrollHeight*scale+8)+'px'};let shells=[...roster.querySelectorAll('.rp-card-shell')];shells.forEach(resize);if(typeof ResizeObserver!=='undefined'){resizeObserver=new ResizeObserver(entries=>entries.forEach(entry=>resize(entry.target)));shells.forEach(shell=>resizeObserver.observe(shell))}}
document.addEventListener('click',e=>{let t=e.target.closest('[data-rp]');if(t?.dataset.rp==='open'&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey))return;if(!t){if(menu&&!menu.contains(e.target))closeMenu();return}e.preventDefault();e.stopImmediatePropagation();let d=t.dataset,g=gang(),f=g?.fighters.find(x=>x.id===d.id);if(d.rp==='menu'){if(menu?.dataset.fighter===f.id){closeMenu();return}openMenu(t,f);menu.dataset.fighter=f.id;return}let focusAnchor=menu?.contains(t)?menuAnchor:null;closeMenu();if(focusAnchor?.isConnected)focusAnchor.focus({preventScroll:true});if(!f)return;if(d.rp==='open'){if(Date.now()<suppressCardClickUntil)return;data.selectedFighter=f.id;data.view='fighter';save();requestAnimationFrame(()=>{if(data.view==='fighter'&&data.selectedFighter===f.id){window.scrollTo({top:0,left:0,behavior:'instant'});document.querySelector('.fighter-page')?.focus({preventScroll:true});}})}else if(d.rp==='xp')addXp(f);else if(d.rp==='injury')addInjury(f);else if(d.rp==='damage')lastingDamage(f);else if(d.rp==='restore')FighterParity.changeStatus(f,'Active');else if(d.rp==='equipment'){let item=f.equipment.find(x=>x.id===d.equipment);if(item)equipmentInfo(f,item)}},true);
document.addEventListener('change',e=>{if(e.target.matches('[data-rp-view]')){data.rosterView=e.target.value;save()}});
document.addEventListener('keydown',e=>{let card=e.target.closest('.rp-card');if(e.key==='Escape'&&menu){e.preventDefault();e.stopImmediatePropagation();closeMenu(true);return}if(menu?.contains(e.target)&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();let items=[...menu.querySelectorAll('button:not(:disabled)')],index=items.indexOf(e.target);items[(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();return}if(card&&e.target===card&&['Enter',' '].includes(e.key)){e.preventDefault();card.click()}});
document.addEventListener('dragstart',e=>{let shell=e.target.closest('[data-rp-fighter]');if(!shell)return;dragged=shell.dataset.rpFighter;e.dataTransfer?.setData('text/plain',dragged);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';shell.classList.add('rp-dragging');closeMenu()});
document.addEventListener('dragover',e=>{let shell=e.target.closest('[data-rp-fighter]');if(!shell||!dragged)return;e.preventDefault();document.querySelectorAll('.rp-drop-target').forEach(x=>x.classList.remove('rp-drop-target'));shell.classList.add('rp-drop-target')});
document.addEventListener('drop',e=>{let shell=e.target.closest('[data-rp-fighter]');if(!shell||!dragged)return;e.preventDefault();suppressCardClickUntil=Date.now()+500;let from=dragged;dragged='';reorder(from,shell.dataset.rpFighter)});
document.addEventListener('dragend',()=>{dragged='';document.querySelectorAll('.rp-dragging,.rp-drop-target').forEach(x=>x.classList.remove('rp-dragging','rp-drop-target'))});
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||e.target.closest('button'))return;let card=e.target.closest('.rp-card');if(!card)return;pointerDrag={id:card.dataset.id,x:e.clientX,y:e.clientY,active:false};longPress=setTimeout(()=>{if(!pointerDrag)return;pointerDrag.active=true;dragged=pointerDrag.id;card.closest('.rp-card-shell').classList.add('rp-dragging');card.style.touchAction='none';closeMenu()},500)},{passive:true});
document.addEventListener('pointermove',e=>{if(!pointerDrag)return;if(!pointerDrag.active){if(Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)>10){clearTimeout(longPress);pointerDrag=null}return}e.preventDefault();let shell=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-rp-fighter]');document.querySelectorAll('.rp-drop-target').forEach(x=>x.classList.remove('rp-drop-target'));if(shell)shell.classList.add('rp-drop-target')},{passive:false});
document.addEventListener('pointerup',e=>{clearTimeout(longPress);if(pointerDrag?.active){let shell=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-rp-fighter]');suppressCardClickUntil=Date.now()+500;if(shell)reorder(pointerDrag.id,shell.dataset.rpFighter)}pointerDrag=null;dragged='';document.querySelectorAll('.rp-dragging,.rp-drop-target').forEach(x=>x.classList.remove('rp-dragging','rp-drop-target'))});
